import {getProfile,saveProfile,clearProfile,defaultAvatar} from './profile-store.js?v=30';
const main=document.querySelector('#account-main');let lang='en',stage='login',email='',busy=false,session=null;
lang=window.PopomoLocale.get();try{session=getProfile();if(session)stage='account';}catch{}
const t=(zh,en)=>lang==='en'?en:zh;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const google=`<svg viewBox="0 0 24 24" aria-hidden="true"><path fill="#4285F4" d="M21.6 12.23c0-.71-.06-1.39-.18-2.05H12v3.88h5.38a4.6 4.6 0 0 1-2 3.02v2.51h3.23c1.89-1.74 2.99-4.3 2.99-7.36Z"/><path fill="#34A853" d="M12 22c2.7 0 4.96-.9 6.61-2.41l-3.23-2.51c-.9.6-2.04.96-3.38.96-2.6 0-4.8-1.76-5.59-4.12H3.07v2.59A10 10 0 0 0 12 22Z"/><path fill="#FBBC05" d="M6.41 13.92A6 6 0 0 1 6.1 12c0-.67.11-1.32.31-1.92V7.49H3.07A10 10 0 0 0 2 12c0 1.61.39 3.14 1.07 4.51l3.34-2.59Z"/><path fill="#EA4335" d="M12 5.96c1.47 0 2.79.51 3.82 1.51l2.87-2.87A9.59 9.59 0 0 0 12 2a10 10 0 0 0-8.93 5.49l3.34 2.59C7.2 7.72 9.4 5.96 12 5.96Z"/></svg>`;
const facebook=`<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="11" fill="#1877F2"/><path fill="#fff" d="M13.6 23v-9h3l.45-3.5H13.6V8.26c0-1.01.28-1.7 1.73-1.7h1.84V3.44a24.6 24.6 0 0 0-2.68-.14c-2.65 0-4.46 1.62-4.46 4.59v2.61h-3V14h3v9z"/></svg>`;
function render(){lang=window.PopomoLocale?.get()||lang;document.body.dataset.accountStage=stage;document.title=t(stage==='account'?'POPOMO · 个人中心':'POPOMO · 登录',stage==='account'?'POPOMO · My account':'POPOMO · Sign in');document.documentElement.lang=lang==='en'?'en':'zh-CN';document.querySelector('#flow-language').value=lang;document.querySelectorAll('[data-zh]').forEach(el=>el.textContent=el.dataset[lang==='en'?'en':'zh']);main.classList.toggle('is-profile',stage==='account');if(stage==='account'){main.innerHTML=account();bind();return;}main.innerHTML=`<section class="account-shell"><aside class="account-story"><p class="account-kicker">A LITTLE MORE YOU.</p><div class="account-story-copy"><span class="account-spark" aria-hidden="true"><svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m16 2 4 10 10 4-10 4-4 10-4-10L2 16l10-4Z"/></svg></span><h1>${t('把灵感，<br>变成你的日常。','A little inspiration.<br>A little more you.')}</h1><p>${t('收藏喜欢的设计，让每一次创作都有迹可循。','Keep the designs you love. Make every creation your own.')}</p></div><div class="account-gift"><span class="gift-icon" aria-hidden="true"><svg viewBox="0 0 32 32" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m16 2 4 10 10 4-10 4-4 10-4-10L2 16l10-4Z"/></svg></span><div><span>${t('新朋友的见面礼','A welcome gift for you')}</span><strong>${t('5 次 AI 创作','5 AI creations')}</strong><small>${t('首次注册领取 · 无需订阅','On your first sign-up · No subscription')}</small></div></div><p class="account-story-bottom">YOUR PHOTO. YOUR EVERYDAY.</p></aside><section class="account-form-panel">${stage==='account'?account():login()}</section></section>`;bind();}
function login(){return `<a class="account-back" href="./">← ${t('返回首页','Back to home')}</a><p class="account-kicker">YOUR POPOMO ACCOUNT</p><h2>${t(stage==='verify'?'验证你的邮箱':'欢迎来到 POPOMO',stage==='verify'?'Verify your email':'Welcome to POPOMO')}</h2><p class="account-intro">${t(stage==='verify'?'输入邮箱验证码，继续你的创作。':'登录，保存你的每一份灵感。',stage==='verify'?'Enter your email code to continue creating.':'Sign in and keep every little inspiration.')}</p>${stage==='verify'?`<form id="code-form"><label for="login-code">${t('邮箱验证码','Email code')}</label><p class="code-address">${esc(email)}</p><input id="login-code" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" minlength="6" maxlength="6" placeholder="000000" required><button class="primary account-submit" ${busy?'disabled':''}>${t('验证并登录','Verify and sign in')} →</button><button type="button" class="account-change" id="change-email">${t('更换邮箱','Use another email')}</button></form>`:`<div class="social-logins"><button class="social-login tertiary" aria-label="Google" data-provider="Google" ${busy?'disabled':''}>${google}<span>Google</span><span class="social-arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 19 19 5M5 5h14v14"/></svg></span></button><button class="social-login tertiary" aria-label="Facebook" data-provider="Facebook" ${busy?'disabled':''}>${facebook}<span>Facebook</span><span class="social-arrow" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M5 19 19 5M5 5h14v14"/></svg></span></button></div><div class="account-divider"><span>${t('或使用邮箱登录','or continue with email')}</span></div><form id="email-form"><label for="login-email">${t('邮箱地址','Email address')}</label><input id="login-email" name="email" type="email" autocomplete="email" placeholder="you@example.com" value="${esc(email)}" required><button class="primary account-submit" ${busy?'disabled':''}>${t('获取验证码','Get verification code')} <span aria-hidden="true">→</span></button></form>`}<p class="account-status" role="status" aria-live="polite">${busy?t('正在连接…','Connecting…'):''}</p><p class="account-note">${t('首次登录将自动创建账号。','Your account is created on your first sign-in.')}</p>`;}
function account(){return `<section class="profile-page"><div class="profile-heading"><p class="account-kicker">YOUR POPOMO ACCOUNT</p><h1>${t('多一点你的风格。','A little more you.')}</h1><p>${t('管理个人资料和你的创作次数。','Your profile and creative credits, in one place.')}</p></div><div class="profile-grid"><section class="profile-card profile-identity"><button class="profile-photo" id="edit-avatar" aria-label="${t('修改头像','Change avatar')}"><img src="${esc(session.avatar||defaultAvatar)}" alt="${t('个人头像','Profile avatar')}"><span>✎</span></button><h2>${esc(session.nickname||t('创作新朋友','Creative friend'))}</h2><p>${esc(session.email||t(`${session.provider} 账号`,`${session.provider} account`))}</p><span class="profile-verified">✓ ${t(session.email?'邮箱已验证':'账号已登录',session.email?'Email verified':'Signed in')}</span><nav><a class="primary" href="./my-designs.html">${t('我的设计','My designs')} ↗</a><a class="secondary" href="./checkout.html?view=orders">${t('我的订单','My orders')} ↗</a></nav><button id="sign-out" class="account-change tertiary">${t('退出登录','Sign out')}</button></section><div class="profile-content"><section class="profile-card"><h2>${t('我的创作次数','My creative credits')}</h2><div class="profile-credits"><div><strong>${session.giftCredits??5}</strong><span>${t('剩余赠送次数','Gift credits remaining')}</span></div><div><strong>${session.monthlyCredits??0}</strong><span>${t('剩余月度次数','Monthly credits remaining')}</span></div></div><p class="profile-help">${t('注册赠送和后台补发合并使用，生成失败会退还次数。','Gift and bonus credits are combined. Failed generations are refunded.')}</p><details class="credit-history"><summary>${t('积分变动','Credit history')}<span aria-hidden="true">＋</span></summary><div><span>${t('注册赠送','Welcome gift')}<small>${new Date(session.createdAt).toLocaleDateString(lang==='en'?'en-US':'zh-CN')}</small></span><strong>+5</strong></div></details></section><section class="profile-card"><h2>${t('个人资料','Profile details')}</h2><form id="profile-form"><label for="profile-nickname">${t('昵称','Nickname')}</label><input id="profile-nickname" name="nickname" maxlength="24" placeholder="${t('希望我们怎么称呼你？','What should we call you?')}" value="${esc(session.nickname||'')}" required><small class="profile-help">${t('最多 24 个字符','Up to 24 characters')}</small><button class="primary" type="submit">${t('保存个人信息','Save profile')}</button><p id="profile-status" role="status" aria-live="polite"></p></form><p class="profile-help profile-created">${t('注册于','Joined')} ${new Date(session.createdAt).toLocaleDateString(lang==='en'?'en-US':'zh-CN')}<br>${t('AI 次数与账号绑定。','AI credits are linked to your account.')}</p></section></div></div></section>`;}
function successModal(){const dialog=document.createElement('dialog');dialog.className='login-success';dialog.setAttribute('aria-labelledby','login-success-title');dialog.innerHTML=`<span class="success-ring" aria-hidden="true">✓</span><h2 id="login-success-title">${t('登录成功','You’re signed in')}</h2><p>${t('欢迎来到 POPOMO，让灵感继续。','Welcome to POPOMO. Keep your inspiration going.')}</p><button class="primary">${t('进入个人中心','Go to my account')} →</button>`;document.body.append(dialog);dialog.querySelector('button').onclick=()=>dialog.close();dialog.addEventListener('close',()=>{dialog.remove();document.querySelector('#edit-avatar')?.focus();},{once:true});dialog.showModal();}
function avatarModal(){let selected=session.avatar||defaultAvatar;const dialog=document.createElement('dialog');dialog.className='avatar-dialog';dialog.setAttribute('aria-labelledby','avatar-title');dialog.innerHTML=`<header><h2 id="avatar-title">${t('修改头像','Change avatar')}</h2><button type="button" class="avatar-close" aria-label="${t('关闭','Close')}">×</button></header><img class="avatar-large" src="${esc(selected)}" alt="${t('头像预览','Avatar preview')}"><p>${t('选择喜欢的虚拟头像，或上传你的照片。','Choose an avatar, or upload your own photo.')}</p><div class="avatar-options">${[1,2,3,4].map(i=>`<button data-avatar="./assets/avatars/avatar-${i}-v30.svg" aria-label="${t('头像','Avatar')} ${i}" aria-pressed="${selected===`./assets/avatars/avatar-${i}-v30.svg`}"><img src="./assets/avatars/avatar-${i}-v30.svg" alt=""></button>`).join('')}</div><button class="secondary avatar-upload">${t('上传照片','Upload photo')}</button><input type="file" accept="image/jpeg,image/png,image/webp" hidden><p class="avatar-error" role="alert"></p><footer><button class="tertiary avatar-cancel">${t('取消','Cancel')}</button><button class="primary avatar-save">${t('保存头像','Save avatar')}</button></footer>`;document.body.append(dialog);const preview=dialog.querySelector('.avatar-large');const select=src=>{selected=src;preview.src=src;dialog.querySelectorAll('[data-avatar]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.avatar===src)));};dialog.querySelectorAll('[data-avatar]').forEach(b=>b.onclick=()=>select(b.dataset.avatar));dialog.querySelector('.avatar-upload').onclick=()=>dialog.querySelector('input').click();dialog.querySelector('input').onchange=async e=>{const file=e.target.files[0];if(!file)return;const error=dialog.querySelector('.avatar-error');error.textContent='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)){error.textContent=t('请选择 JPG、PNG 或 WebP 图片。','Choose a JPG, PNG or WebP image.');return;}const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();const size=Math.min(image.width,image.height),canvas=document.createElement('canvas');canvas.width=256;canvas.height=256;canvas.getContext('2d').drawImage(image,(image.width-size)/2,(image.height-size)/2,size,size,0,0,256,256);select(canvas.toDataURL('image/jpeg',.88));}catch{error.textContent=t('无法读取这张图片，请重试。','Could not read the image. Please retry.');}finally{URL.revokeObjectURL(url);}};dialog.querySelector('.avatar-save').onclick=()=>{try{session=saveProfile({...session,avatar:selected});dialog.close();render();document.querySelector('#profile-status').textContent=t('头像已更新','Avatar updated');}catch{dialog.querySelector('.avatar-error').textContent=t('保存失败，请重试。','Could not save. Please retry.');}};dialog.querySelector('.avatar-close').onclick=dialog.querySelector('.avatar-cancel').onclick=()=>dialog.close();dialog.addEventListener('close',()=>dialog.remove(),{once:true});dialog.showModal();}
function finish(provider){try{session=saveProfile({provider,...(provider==='Email'?{email}:{}),nickname:'',avatar:defaultAvatar,giftCredits:5,monthlyCredits:0,createdAt:Date.now()});stage='account';busy=false;render();successModal();}catch{busy=false;stage='login';render();main.querySelector('.account-status').textContent=t('暂时无法登录，请重试。','Could not sign in. Please retry.');}}
function bind(){main.querySelector('#edit-avatar')?.addEventListener('click',avatarModal);main.querySelector('#profile-form')?.addEventListener('submit',e=>{e.preventDefault();const field=main.querySelector('#profile-nickname'),nickname=field.value.trim();if(!nickname){field.setCustomValidity(t('请输入昵称','Enter a nickname'));field.reportValidity();return;}field.setCustomValidity('');try{session=saveProfile({...session,nickname});render();main.querySelector('#profile-status').textContent=t('个人信息已保存','Profile saved');}catch{main.querySelector('#profile-status').textContent=t('保存失败，请重试。','Could not save. Please retry.');}});main.querySelector('#profile-nickname')?.addEventListener('input',e=>e.target.setCustomValidity(''));main.querySelectorAll('[data-provider]').forEach(button=>button.onclick=()=>{if(busy)return;busy=true;render();setTimeout(()=>finish(button.dataset.provider),900);});main.querySelector('#email-form')?.addEventListener('submit',e=>{e.preventDefault();email=main.querySelector('#login-email').value.trim();stage='verify';render();main.querySelector('#login-code').focus();});main.querySelector('#code-form')?.addEventListener('submit',e=>{e.preventDefault();if(!/^[0-9]{6}$/.test(main.querySelector('#login-code').value))return;finish('Email');});main.querySelector('#change-email')?.addEventListener('click',()=>{stage='login';render();});main.querySelector('#sign-out')?.addEventListener('click',()=>{clearProfile();session=null;stage='login';render();});}
render();

window.PopomoLocale.subscribe(()=>render());
